from pathlib import Path
import hashlib,json,os,stat,subprocess,tempfile
out=Path(__file__).resolve().parent;root=Path(tempfile.mkdtemp(prefix='gitfleet-g07-object-export-',dir='/private/tmp'));source=root/'source';transport=root/'transport.git'
