source.mkdir();git(source,'-c','init.templateDir=','init','-q','-b','main');git(source,'config','user.name','G07 export fixture');git(source,'config','user.email','fixture@example.invalid');(source/'approved.txt').write_text('Approved branch only\n');git(source,'add','approved.txt');git(source,'commit','-qm','Approved source');approved=git(source,'rev-parse','HEAD').strip();git(source,'checkout','-qb','unselected');(source/'unselected.txt').write_text('Unselected branch must not be exported\n');git(source,'add','unselected.txt');git(source,'commit','-qm','Unselected source');unselected_blob=git(source,'rev-parse','HEAD:unselected.txt').strip();git(source,'checkout','-q','main');git(source,'config','gitfleet.sourceOnly','must-not-be-loaded')
def snap():return {str(p.relative_to(source)):{'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'mode':stat.S_IMODE(p.stat().st_mode)} for p in source.rglob('*') if p.is_file()}
before=snap();git(root,'-c','init.templateDir=','init','--bare','-q',str(transport));objects=source/'.git/objects';closure=git(transport,'rev-list','--objects','--no-object-names',approved.decode(),objects=objects);wanted=set(closure.splitlines());assert unselected_blob not in wanted;details=git(transport,'cat-file','--batch-check=%(objectname) %(objectsize)',input=closure,objects=objects);size=sum(int(line.split()[1]) for line in details.splitlines());assert len(wanted)<=10000 and size<=64*1024*1024
packed=git(transport,'pack-objects','--stdout','--revs',input=approved+b'\n',objects=objects);git(transport,'index-pack','--stdin','--strict',input=packed);git(transport,'update-ref','refs/heads/approved-source',approved.decode());git(transport,'fsck','--strict','--full','--no-reflogs','--no-dangling',approved.decode());actual=set(git(transport,'cat-file','--batch-all-objects','--batch-check=%(objectname)').splitlines());assert actual==wanted;assert unselected_blob not in actual;assert b'gitfleet.sourceonly' not in git(transport,'config','--null','--list').lower();assert snap()==before
result={'root':str(root),'approved_oid':approved.decode(),'unselected_blob':unselected_blob.decode(),'object_count':len(actual),'uncompressed_bytes':size,'pack_bytes':len(packed),'pack_sha256':hashlib.sha256(packed).hexdigest(),'exact_approved_reachable_closure_only':True,'unselected_branch_blob_absent':True,'source_config_not_loaded':True,'managed_repository_exact_files_modes':True,'isolated_objects_fsck_passed':True,'primitive_only_not_application_acceptance':True};(out/'pack-result.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2))
